llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "Diflunisal absolute bioavailability was 89.5% in a volunteer based on AUC after equivalent i.v. and oral doses, well above the 20% threshold."
    },
    {
      "card_ids": ["C02"],
      "claim": "Telmisartan absolute bioavailability was 57.4% in healthy male volunteers for a 160 mg tablet relative to IV, above the 20% threshold."
    },
    {
      "card_ids": ["C17"],
      "claim": "Pazopanib absolute bioavailability was estimated at a mean of 21.4% (range 13.5–38.9%) in cancer patients, with the mean above the 20% threshold."
    }
  ],
  "confidence": "moderate",
  "contradictory_card_ids": [],
  "decision_summary": "The most direct absolute human bioavailability records (diflunisal 89.5%, telmisartan 57.4%, pazopanib mean 21.4%) all support F ≥ 20%; no affirmative sub-20% record was identified. Confidence is moderate because no cystic fibrosis-specific data are available and some retrieved records are qualitative or unspecified.",
  "evidence_gaps": [
    "No bioavailability measurements under cystic fibrosis conditions; evidence is transferred from other human populations/conditions.",
    "Some records use unspecified bioavailability type or qualitative descriptors (e.g., 'good', 'high', 'rapid and complete'), limiting quantitative threshold comparison.",
    "C13 reports 20–40% with qualitative 'low' and unspecified type; it is ambiguous relative to the 20% threshold and was not used as affirmative evidence."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C18", "C02", "C17"],
  "revision_action": "initial",
  "supportive_card_ids": ["C18", "C02", "C17"]
}

